cases.setup:
create table p.parent (
  id serial primary key,
  name text not null
);

create table p.child (
  id serial primary key,
  parent_id integer,
  name text not null,
  constraint child_parent_fkey foreign key (parent_id)
    references p.parent (id)
);

operations.source:
mutation {
  c1: createParent(
    input: {
      parent: {
        name: "test"
        children: {
          create: [{
            name: "test child"
          }]
        }
      }
    }
  ) {
    parent {
      id
    }
  }

  c2: createChild(
    input: {
      child: {
        name: "child"
        parent: {
          create: {
            name: "child's parent"
          }
        }
      }
    }
  ) {
    child {
      id
    }
  }
}

