cases.setup:
create table p.parent (
  id uuid primary key default public.uuid_generate_v4(),
  name text not null
);
create table p.child (
  id uuid primary key default public.uuid_generate_v4(),
  parent_id uuid references p.parent on delete set null,
  name text not null
);

operations.source:
mutation {
  createParent(
    input: {
      parent: {
        name: "test"
        childrenUsingRowId: {
          create: {
            name: "test child"
          }
        }
      }
    }
  ) {
    parent {
      id
      rowId
      childrenByParentId {
        nodes {
          id
          rowId
        }
      }
    }
  }
}
